      schematicView: analogMixedNormalizeManufacturerView(item?.schematicView || item?.manufacturerView || {}, item?.pins || [], item || {}),
      vendorMetadata: item?.vendorMetadata && typeof item.vendorMetadata === "object" ? item.vendorMetadata : {},
