function hdlSourceWithoutComments(code = "") {
  return String(code || "")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/(^|[^:])\/\/.*$/gm, "$1");
}

function hdlModuleNames(code = "") {
  return [...String(code || "").matchAll(/\bmodule\s+([A-Za-z_$][\w$]*)/g)].map((match) => match[1]);
}

const compileIpBlockLibrary = [
  {
    id: "clock-divider",
    label: "Clock divider",
    fileName: "ip/clock_divider.sv",
    description: "Parameterized counter divider for creating slower enable ticks from a fast FPGA clock.",
    code: `module clock_divider #(
  parameter integer DIVISOR = 50000000
) (
  input  logic clk,
  input  logic rst,
  output logic tick
);
  localparam integer COUNT_WIDTH = $clog2(DIVISOR);
  logic [COUNT_WIDTH-1:0] count;

  always_ff @(posedge clk or posedge rst) begin
    if (rst) begin
      count <= '0;
      tick <= 1'b0;
    end else if (count == DIVISOR - 1) begin
      count <= '0;
      tick <= 1'b1;
    end else begin
      count <= count + 1'b1;
      tick <= 1'b0;
    end
  end
endmodule
`
  },
  {
    id: "edge-detector",
    label: "Edge detector",
    fileName: "ip/edge_detector.sv",
    description: "Single-cycle rising and falling edge pulse generator for synchronized control signals.",
    code: `module edge_detector (
  input  logic clk,
  input  logic rst,
  input  logic signal_in,
  output logic rising_edge,
  output logic falling_edge
);
  logic signal_d;

  always_ff @(posedge clk or posedge rst) begin
    if (rst) signal_d <= 1'b0;
    else signal_d <= signal_in;
  end

  assign rising_edge = signal_in & ~signal_d;
  assign falling_edge = ~signal_in & signal_d;
endmodule
`
  },
  {
    id: "two-flop-synchronizer",
    label: "Two-flop synchronizer",
    fileName: "ip/two_flop_synchronizer.sv",
    description: "Metastability-reduction synchronizer for single-bit asynchronous inputs crossing into a clock domain.",
    code: `module two_flop_synchronizer (
  input  logic clk,
  input  logic rst,
  input  logic async_in,
  output logic sync_out
);
  logic sync_1;

  always_ff @(posedge clk or posedge rst) begin
    if (rst) begin
      sync_1 <= 1'b0;
      sync_out <= 1'b0;
    end else begin
      sync_1 <= async_in;
      sync_out <= sync_1;
    end
  end
endmodule
`
  },
  {
    id: "pwm-core",
    label: "PWM core",
    fileName: "ip/pwm_core.sv",
    description: "Parameterized PWM generator with duty input and terminal-count carrier.",
    code: `module pwm_core #(
  parameter integer WIDTH = 8
) (
  input  logic clk,
  input  logic rst,
  input  logic [WIDTH-1:0] duty,
  output logic pwm
);
  logic [WIDTH-1:0] counter;

  always_ff @(posedge clk or posedge rst) begin
    if (rst) counter <= '0;
    else counter <= counter + 1'b1;
  end

  assign pwm = counter < duty;
endmodule
`
  },
  {
    id: "uart-tx",
    label: "UART transmitter",
    fileName: "ip/uart_tx.sv",
    description: "Small UART transmit block with ready/busy handshaking and configurable baud divisor.",
    code: `module uart_tx #(
  parameter integer CLKS_PER_BIT = 434
) (
  input  logic clk,
  input  logic rst,
  input  logic start,
  input  logic [7:0] data,
  output logic tx,
  output logic busy
);
  typedef enum logic [1:0] {IDLE, START, DATA, STOP} state_t;
  state_t state;
  logic [15:0] baud_count;
  logic [2:0] bit_index;
  logic [7:0] shifter;

  always_ff @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= IDLE;
      tx <= 1'b1;
      busy <= 1'b0;
      baud_count <= '0;
      bit_index <= '0;
      shifter <= '0;
    end else begin
      case (state)
        IDLE: begin
          tx <= 1'b1;
          busy <= 1'b0;
          if (start) begin
            busy <= 1'b1;
            shifter <= data;
            baud_count <= '0;
            state <= START;
          end
        end
        START: begin
          tx <= 1'b0;
          if (baud_count == CLKS_PER_BIT - 1) begin
            baud_count <= '0;
            bit_index <= '0;
            state <= DATA;
          end else baud_count <= baud_count + 1'b1;
        end
        DATA: begin
          tx <= shifter[bit_index];
          if (baud_count == CLKS_PER_BIT - 1) begin
            baud_count <= '0;
            if (bit_index == 3'd7) state <= STOP;
            else bit_index <= bit_index + 1'b1;
          end else baud_count <= baud_count + 1'b1;
        end
        STOP: begin
          tx <= 1'b1;
          if (baud_count == CLKS_PER_BIT - 1) state <= IDLE;
          else baud_count <= baud_count + 1'b1;
        end
      endcase
    end
  end
endmodule
`
  },
  {
    id: "axi-lite-register",
    label: "AXI-lite register",
    fileName: "ip/axi_lite_register_stub.sv",
    description: "Starter AXI-lite style register shell for integrating control/status registers.",
    code: `module axi_lite_register_stub #(
  parameter integer WIDTH = 32
) (
  input  logic clk,
  input  logic rst,
  input  logic write_enable,
  input  logic [WIDTH-1:0] write_data,
  output logic [WIDTH-1:0] read_data
);
  always_ff @(posedge clk or posedge rst) begin
    if (rst) read_data <= '0;
    else if (write_enable) read_data <= write_data;
  end
endmodule
`
  }
];

function hdlDeclaredPortsFromModuleBody(body = "") {
  const ports = [];
  const seen = new Set();
  const cleaned = String(body || "");
  for (const match of cleaned.matchAll(/\b(input|output|inout)\b\s+(?:wire|reg|logic|signed|unsigned|tri|bit\s+)*(?:\[[^\]]+\]\s*)?([^;()]+)/gi)) {
    const direction = String(match[1] || "").toLowerCase();
    String(match[2] || "")
      .split(",")
      .map((part) => part.replace(/=.*/, "").replace(/\[[^\]]+\]/g, "").trim())
      .map((part) => part.split(/\s+/).pop())
      .filter((name) => /^[A-Za-z_$][\w$]*$/.test(name || ""))
      .forEach((name) => {
        const key = `${direction}:${name}`;
        if (seen.has(key)) return;
        seen.add(key);
        ports.push({ name, direction });
      });
  }
  return ports.slice(0, 80);
}

function hdlSynthesisGraphFromFiles(files = []) {
  const moduleBodies = new Map();
  const moduleNames = new Set();
  const hdlFiles = files.filter((file) => isHdlLanguage(file.language));
  hdlFiles.forEach((file) => {
    const source = hdlSourceWithoutComments(file.code || "");
    for (const match of source.matchAll(/\bmodule\s+([A-Za-z_$][\w$]*)\b([\s\S]*?)\bendmodule\b/g)) {
      moduleNames.add(match[1]);
      moduleBodies.set(match[1], { body: match[2] || "", fileName: file.fileName || file.title || "source" });
    }
  });
  const instantiated = new Set();
  const edges = [];
  const instancePattern = /^\s*([A-Za-z_$][\w$]*)\s*(?:#\s*\([\s\S]*?\)\s*)?([A-Za-z_$][\w$]*)\s*\(/gm;
  moduleBodies.forEach((entry, parent) => {
    for (const match of entry.body.matchAll(instancePattern)) {
      const child = match[1];
      const instance = match[2];
      if (!moduleNames.has(child) || child === parent) continue;
      instantiated.add(child);
      edges.push({ from: parent, to: child, instance });
    }
  });
  const nodes = [...moduleNames].map((id) => ({
    id,
    label: id,
    kind: "module",
    type: "source module",
    fileName: moduleBodies.get(id)?.fileName || "",
    ports: hdlDeclaredPortsFromModuleBody(moduleBodies.get(id)?.body || ""),
    portCount: hdlDeclaredPortsFromModuleBody(moduleBodies.get(id)?.body || "").length
  }));
  const topModule = nodes.find((node) => !instantiated.has(node.id))?.id || nodes[0]?.id || "";
  return {
    nodes,
    edges,
    topModule,
    target: defaultFpgaTarget,
    sources: hdlFiles.map((file) => ({
      fileName: file.fileName || file.relativePath || "source",
      relativePath: compileFilePath(file),
      language: normalizeCodeLanguage(file.language),
      role: file.role || "design",
      type: file.fileType || file.type || file.role || "source",
      moduleNames: hdlModuleNames(file.code || ""),
      lines: String(file.code || "").split(/\r?\n/).length,
      bytes: new Blob([String(file.code || "")]).size,
      simulator: "Icarus Verilog / vvp",
      synthesisTool: "Yosys"
    })),
    timing: {
      status: "Source timing review",
      notes: ["Run Synthesize with Yosys to create netlist-level timing structure and cell/register counts."]
    },
    summary: {
      moduleCount: nodes.length,
      instanceCount: edges.length,
      designFileCount: hdlFiles.length
    },
    generatedAt: new Date().toISOString()
  };
}

function activeSynthesisDiagram(project, file = activeCompileFile(project)) {
  const workspace = ensureCompileCode(project);
  const files = Array.isArray(workspace.files) ? workspace.files : [];
  const designFiles = files.filter((item) => isHdlLanguage(item.language) && item.role !== "testbench");
  const fallbackFiles = designFiles.length ? designFiles : (files.length ? files : (file ? [file] : []));
  const fallbackGraph = hdlSynthesisGraphFromFiles(fallbackFiles);
  const synthesis = file?.lastResult?.synthesis || workspace.synthesis || {};
  const graph = synthesis.graph || fallbackGraph;
  const selectedTop = workspace.synthesisTopModule && Array.isArray(graph.nodes) && graph.nodes.some((node) => node.id === workspace.synthesisTopModule)
    ? workspace.synthesisTopModule
    : graph.topModule;
  return {
    graph: { ...graph, topModule: selectedTop },
    tool: synthesis.tool || "Source parser",
    available: synthesis.available !== false,
    cacheHit: Boolean(synthesis.cacheHit),
    summary: synthesis.summary || synthesis.graph?.summary || fallbackGraph.summary || {},
    sources: Array.isArray(synthesis.sources) && synthesis.sources.length ? synthesis.sources : (graph.sources || fallbackGraph.sources || []),
    constraints: Array.isArray(synthesis.constraints) ? synthesis.constraints : [],
    target: synthesis.target || graph.target || fallbackGraph.target || defaultFpgaTarget,
    nets: Array.isArray(graph.nets) ? graph.nets : [],
    objects: Array.isArray(graph.objects) ? graph.objects : [],
    timing: synthesis.timing || graph.timing || fallbackGraph.timing || {},
    terminal: synthesis.terminal || "",
    outputPath: synthesis.outputPath || "",
    netlistPath: synthesis.netlistPath || "",
    dotPath: synthesis.dotPath || "",
    synthesizedAt: synthesis.synthesizedAt || synthesis.generatedAt || ""
  };
}

function synthesisNodeHaystack(node = "") {
  return [
    node.id,
    node.label,
    node.type,
    node.kind,
    node.direction,
    node.fileName,
    node.source
  ].map((part) => String(part || "").toLowerCase()).join(" ");
}

function synthesisEdgeHaystack(edge = "") {
  return [
    edge.from,
    edge.to,
    edge.instance,
    edge.type,
    edge.net,
    edge.fromPort,
    edge.toPort,
    edge.direction
  ].map((part) => String(part || "").toLowerCase()).join(" ");
}

function renderSynthesisSummaryChips(synthesis = {}, graph = {}) {
  const summary = synthesis.summary || graph.summary || {};
  const target = synthesis.target || graph.target || defaultFpgaTarget;
  const cellTypes = Array.isArray(summary.cellTypes) ? summary.cellTypes.slice(0, 8) : [];
  const chips = [
    synthesis.cacheHit ? "Cache hit" : "",
    synthesis.tool || "",
    target?.board || "",
    target?.part || "",
    graph.netlist ? "Yosys netlist" : "Source graph",
    summary.moduleCount !== undefined ? `${summary.moduleCount} modules` : "",
    summary.cellCount !== undefined ? `${summary.cellCount} cells` : "",
    summary.netCount !== undefined ? `${summary.netCount} nets` : "",
    summary.portCount !== undefined ? `${summary.portCount} ports` : "",
    graph.truncated ? "Preview truncated" : ""
  ].filter(Boolean);
  return `
    <div class="compile-synthesis-meta">
      ${chips.map((chip) => `<span>${escapeHtml(chip)}</span>`).join("")}
      ${cellTypes.map((item) => `<span>${escapeHtml(item.type)}: ${Number(item.count) || 0}</span>`).join("")}
    </div>
  `;
}

function synthesisExplorerViews() {
  return [
    { id: "tree", label: "Tree" },
    { id: "nets", label: "Nets" },
    { id: "objects", label: "Objects" },
    { id: "sources", label: "Sources" },
    { id: "ip", label: "IP blocks" },
    { id: "timing", label: "Timing" }
  ];
}

function synthesisNodeDimensions(node = {}, expansionLevel = 0, detailCount = 0) {
  const labelLength = String(node.label || node.id || "").length;
  const typeLength = String(node.type || node.fileName || node.kind || "").length;
  const portCount = Math.max(Number(node.portCount) || 0, Array.isArray(node.ports) ? node.ports.length : 0);
  const expansionWidth = expansionLevel ? 78 + expansionLevel * 22 : 0;
  const expansionHeight = expansionLevel ? 40 + Math.min(12, Math.max(detailCount, portCount)) * 13 + (expansionLevel > 1 ? 22 : 0) : 0;
  return {
    width: Math.min(440, Math.max(expansionLevel ? 220 : 112, Number(node.nodeWidth) || 84 + Math.max(labelLength, typeLength) * 5.5) + expansionWidth),
    height: Math.min(330, Math.max(44, Number(node.nodeHeight) || 48 + Math.min(5, portCount) * 5) + expansionHeight)
  };
}

function synthesisSourceKey(source = {}) {
  return source.relativePath || source.fileName || source.path || "";
}

function renderSynthesisExplorerList(items = [], options = {}) {
  if (!items.length) return `<p class="compile-synthesis-empty">${escapeHtml(options.empty || "No items available.")}</p>`;
  return `
    <div class="compile-synthesis-list">
      ${items.map((item) => `
        <button type="button" ${item.action || ""} title="${escapeHtml(item.title || item.primary || "")}">
          <span>${escapeHtml(item.primary || "")}</span>
          ${item.secondary ? `<small>${escapeHtml(item.secondary)}</small>` : ""}
          ${item.badge ? `<em>${escapeHtml(item.badge)}</em>` : ""}
        </button>
      `).join("")}
    </div>
  `;
}

function renderSynthesisSourceDetails(synthesis = {}, selectedKey = "") {
  const sources = Array.isArray(synthesis.sources) ? synthesis.sources : [];
  const source = sources.find((item) => synthesisSourceKey(item) === selectedKey) || sources[0];
  if (!source) return "";
  const target = synthesis.target || defaultFpgaTarget;
  const rows = [
    ["File", source.fileName || source.relativePath || "source"],
    ["Path", source.relativePath || source.fileName || ""],
    ["Target language", codeLanguageLabel(source.language || "systemverilog")],
    ["FPGA board", source.targetBoard || target.board || ""],
    ["FPGA part", source.targetPart || target.part || ""],
    ["Role", source.role || "design"],
    ["Type", source.type || source.role || "source"],
    ["Simulator", source.simulator || "Icarus Verilog / vvp"],
    ["Synthesis tool", source.synthesisTool || "Yosys"],
    ["Modules", Array.isArray(source.moduleNames) && source.moduleNames.length ? source.moduleNames.join(", ") : "No modules detected"],
    ["Lines", String(source.lines || 0)],
    ["Bytes", String(source.bytes || 0)]
  ];
  return `
    <section class="compile-synthesis-source-details">
      <h4>Source details</h4>
      ${rows.map(([label, value]) => `
        <p>
          <span>${escapeHtml(label)}</span>
          <strong>${escapeHtml(value)}</strong>
        </p>
      `).join("")}
    </section>
  `;
}

function renderSynthesisExplorer(project, synthesis = {}, graph = {}) {
  const workspace = ensureCompileCode(project);
  const view = workspace.synthesisExplorerView || "tree";
  const nodes = Array.isArray(graph.nodes) ? graph.nodes : [];
  const ports = nodes.filter((node) => node.kind === "port");
  const inputs = ports.filter((node) => node.direction === "input");
  const outputs = ports.filter((node) => node.direction === "output");
  const inouts = ports.filter((node) => node.direction === "inout");
  const cells = nodes.filter((node) => node.kind !== "port" && node.kind !== "top");
  const sources = Array.isArray(synthesis.sources) ? synthesis.sources : [];
  const nets = Array.isArray(synthesis.nets) ? synthesis.nets : (Array.isArray(graph.nets) ? graph.nets : []);
  const objects = Array.isArray(synthesis.objects) ? synthesis.objects : (Array.isArray(graph.objects) ? graph.objects : []);
  const timing = synthesis.timing || graph.timing || {};
  const viewButtons = synthesisExplorerViews().map((item) => `
    <button type="button" data-synthesis-view="${escapeHtml(item.id)}" aria-pressed="${view === item.id ? "true" : "false"}">${escapeHtml(item.label)}</button>
  `).join("");
  let body = "";
  if (view === "tree") {
    body = `
      <div class="compile-synthesis-tree">
        <details open>
          <summary>Inputs (${inputs.length})</summary>
          ${renderSynthesisExplorerList(inputs.map((node) => ({ primary: node.label, secondary: node.type, badge: "input" })), { empty: "No input ports." })}
        </details>
        <details open>
          <summary>Logic objects (${cells.length})</summary>
          ${renderSynthesisExplorerList(cells.map((node) => ({ primary: node.label, secondary: node.type || node.kind, badge: `${node.portCount || 0} ports` })), { empty: "No synthesized cells." })}
        </details>
        <details open>
          <summary>Outputs (${outputs.length})</summary>
          ${renderSynthesisExplorerList(outputs.map((node) => ({ primary: node.label, secondary: node.type, badge: "output" })), { empty: "No output ports." })}
        </details>
        ${inouts.length ? `<details><summary>Bidirectional (${inouts.length})</summary>${renderSynthesisExplorerList(inouts.map((node) => ({ primary: node.label, secondary: node.type, badge: "inout" })))}</details>` : ""}
      </div>
    `;
  } else if (view === "nets") {
    body = renderSynthesisExplorerList(nets.slice(0, 160).map((net) => ({
      primary: net.name,
      secondary: `drivers: ${(net.drivers || []).join(", ") || "none"} | loads: ${(net.loads || []).join(", ") || "none"}`,
      badge: `${net.width || 1} bit${Number(net.width) === 1 ? "" : "s"}`
    })), { empty: "Run synthesis to inspect nets." });
  } else if (view === "objects") {
    body = renderSynthesisExplorerList(objects.slice(0, 180).map((object) => ({
      primary: object.name,
      secondary: [object.type, object.source].filter(Boolean).join(" - "),
      badge: object.direction || object.kind || "object"
    })), { empty: "Run synthesis to inspect objects." });
  } else if (view === "sources") {
    body = `
      ${renderSynthesisExplorerList(sources.map((source) => ({
        primary: source.fileName || source.relativePath,
        secondary: `${codeLanguageLabel(source.language)} - ${source.role || "design"} - ${(source.moduleNames || []).join(", ") || "no module"}`,
        badge: `${source.lines || 0} lines`,
        action: `data-synthesis-source="${escapeHtml(synthesisSourceKey(source))}"`
      })), { empty: "No HDL sources were collected." })}
      ${renderSynthesisSourceDetails(synthesis, workspace.synthesisSourceDetails)}
    `;
  } else if (view === "ip") {
    body = `
      <p class="compile-synthesis-help">Add reusable HDL IP into this project workspace, then wire it into your design and synthesize again.</p>
      ${renderSynthesisExplorerList(compileIpBlockLibrary.map((block) => ({
        primary: block.label,
        secondary: block.description,
        badge: "SystemVerilog",
        action: `data-compile-add-ip="${escapeHtml(block.id)}"`
      })), { empty: "No IP blocks available." })}
    `;
  } else if (view === "timing") {
    const notes = Array.isArray(timing.notes) ? timing.notes : [];
    const target = synthesis.target || graph.target || defaultFpgaTarget;
    const constraints = Array.isArray(synthesis.constraints) ? synthesis.constraints : [];
    body = `
      <div class="compile-synthesis-timing">
        <strong>${escapeHtml(timing.status || "Timing analysis")}</strong>
        <p>Target: ${escapeHtml([target.board, target.part].filter(Boolean).join(" - ") || "Nexys A7-100T")}</p>
        <p>Constraints: ${constraints.length ? escapeHtml(constraints.map((file) => file.fileName || file.relativePath).join(", ")) : escapeHtml(target.constraintsHint || "No constraint files selected")}</p>
        <p>Registers: ${Number(timing.registerCount) || 0}</p>
        <p>Combinational cells: ${Number(timing.combinationalCellCount) || 0}</p>
        <p>Memory cells: ${Number(timing.memoryCount) || 0}</p>
        ${notes.length ? `<ul>${notes.map((note) => `<li>${escapeHtml(note)}</li>`).join("")}</ul>` : `<p>Run synthesis to generate structural timing notes.</p>`}
      </div>
    `;
  }
  return `
    <aside class="compile-synthesis-explorer" aria-label="Synthesis explorer">
      <div class="compile-synthesis-view-buttons">${viewButtons}</div>
      <div class="compile-synthesis-view-body">${body}</div>
    </aside>
  `;
}

function synthesisExpansionLevel(workspace = {}, nodeId = "") {
  const expanded = workspace.synthesisExpandedNodes && typeof workspace.synthesisExpandedNodes === "object"
    ? workspace.synthesisExpandedNodes
    : {};
  return Math.max(0, Math.min(3, Math.round(Number(expanded[String(nodeId || "")]) || 0)));
}

function synthesisShortText(value = "", limit = 58) {
  const text = String(value || "").replace(/\s+/g, " ").trim();
  if (text.length <= limit) return text;
  return `${text.slice(0, Math.max(8, limit - 3))}...`;
}

function synthesisNodePorts(node = {}, graph = {}) {
  const ports = [];
  const seen = new Set();
  const pushPort = (name = "", direction = "inout") => {
    const cleanName = String(name || "").trim();
    if (!cleanName) return;
    const cleanDirection = ["input", "output", "inout"].includes(direction) ? direction : "inout";
    const key = `${cleanDirection}:${cleanName}`;
    if (seen.has(key)) return;
    seen.add(key);
    ports.push({ name: cleanName, direction: cleanDirection });
  };
  (Array.isArray(node.ports) ? node.ports : []).forEach((port) => {
    if (typeof port === "string") pushPort(port, "inout");
    else pushPort(port.name || port.label, port.direction || "inout");
  });
  (Array.isArray(graph.edges) ? graph.edges : []).forEach((edge) => {
    if (edge.from === node.id) pushPort(edge.fromPort || edge.net || edge.instance, "output");
    if (edge.to === node.id) pushPort(edge.toPort || edge.net || edge.instance, "input");
  });
  return ports.slice(0, 28);
}

function synthesisChildEntries(node = {}, graph = {}, nodesById = new Map()) {
  const children = [];
  const seen = new Set();
  (Array.isArray(graph.edges) ? graph.edges : []).forEach((edge) => {
    if (edge.from !== node.id) return;
    const child = nodesById.get(edge.to);
    const label = [edge.instance, child?.label || edge.to].filter(Boolean).join(": ");
    if (!label || seen.has(label)) return;
    seen.add(label);
    children.push(label);
  });
  if ((node.kind === "top" || node.id === `module:${graph.topModule}`) && graph.netlist) {
    (Array.isArray(graph.nodes) ? graph.nodes : [])
      .filter((item) => item.kind !== "port" && item.kind !== "top")
      .slice(0, 18)
      .forEach((item) => {
        const label = `${item.label || item.id} (${item.type || item.kind || "cell"})`;
        if (!seen.has(label)) {
          seen.add(label);
          children.push(label);
        }
      });
  }
  return children.slice(0, 18);
}

function synthesisConnectedNetEntries(node = {}, graph = {}) {
  const nets = [];
  const seen = new Set();
  (Array.isArray(graph.edges) ? graph.edges : []).forEach((edge) => {
    if (edge.from !== node.id && edge.to !== node.id) return;
    const label = [edge.net || edge.instance || `${edge.from}->${edge.to}`, Number(edge.width) > 1 ? `${edge.width}b` : ""].filter(Boolean).join(" ");
    if (!label || seen.has(label)) return;
    seen.add(label);
    nets.push(label);
  });
  return nets.slice(0, 18);
}

function synthesisDetailCount(node = {}, graph = {}, level = 0, nodesById = new Map()) {
  if (!level) return 0;
  let count = Math.min(8, synthesisNodePorts(node, graph).length);
  if (level > 1) count += Math.min(6, synthesisChildEntries(node, graph, nodesById).length);
  if (level > 2) count += Math.min(6, synthesisConnectedNetEntries(node, graph).length);
  return Math.max(1, count);
}

function synthesisOrthogonalPath(start, end, index = 0) {
  const lane = ((index % 9) - 4) * 7;
  const forward = end.x >= start.x;
  const midX = forward
    ? start.x + Math.max(38, (end.x - start.x) / 2) + lane
    : Math.max(24, Math.min(start.x, end.x) - 46 - Math.abs(lane));
  if (Math.abs(start.y - end.y) < 4) return `M${start.x},${start.y} L${end.x},${end.y}`;
  return `M${start.x},${start.y} L${midX},${start.y} L${midX},${end.y} L${end.x},${end.y}`;
}

function renderSynthesisNodeDetail(node = {}, graph = {}, level = 0, nodesById = new Map(), position = { x: 0, y: 0 }, size = { width: 120, height: 54 }) {
  if (!level) return "";
  const lines = [];
  const ports = synthesisNodePorts(node, graph);
  if (ports.length) {
    lines.push(`Ports: ${ports.slice(0, 6).map((port) => `${port.direction[0]}:${port.name}`).join(", ")}${ports.length > 6 ? " ..." : ""}`);
  } else {
    lines.push("Ports: inferred from connected nets");
  }
  if (level > 1) {
    const children = synthesisChildEntries(node, graph, nodesById);
    lines.push(children.length ? `Inside: ${children.slice(0, 4).join(", ")}${children.length > 4 ? " ..." : ""}` : "Inside: primitive or leaf block");
  }
  if (level > 2) {
    const nets = synthesisConnectedNetEntries(node, graph);
    lines.push(nets.length ? `Nets: ${nets.slice(0, 4).join(", ")}${nets.length > 4 ? " ..." : ""}` : "Nets: no named nets exposed");
  }
  const detailY = position.y + 64 + Math.min(12, ports.length) * 13;
  return `
    <text class="compile-synthesis-detail" x="${position.x + 12}" y="${detailY}">
      ${lines.slice(0, 8).map((line, index) => `<tspan x="${position.x + 12}" dy="${index ? 16 : 0}">${escapeHtml(synthesisShortText(line, Math.max(48, Math.floor(size.width / 6))))}</tspan>`).join("")}
    </text>
    <text class="compile-synthesis-expand-badge" x="${position.x + size.width - 42}" y="${position.y + 22}">L${level}</text>
  `;
}

function renderSynthesisPortRails(node = {}, graph = {}, level = 0, position = { x: 0, y: 0 }, size = { width: 120, height: 54 }) {
  if (!level) return "";
  const ports = synthesisNodePorts(node, graph);
  const leftPorts = ports.filter((port) => port.direction !== "output").slice(0, 12);
  const rightPorts = ports.filter((port) => port.direction === "output").slice(0, 12);
  const startY = position.y + 54;
  const row = 13;
  const renderPins = (items, side) => items.map((port, index) => {
    const y = startY + index * row;
    const pinX = side === "left" ? position.x : position.x + size.width;
    const textX = side === "left" ? position.x + 10 : position.x + size.width - 10;
    const leadX = side === "left" ? position.x - 10 : position.x + size.width + 10;
    return `
      <line class="compile-synthesis-pin" x1="${leadX}" y1="${y - 4}" x2="${pinX}" y2="${y - 4}"></line>
      <text class="compile-synthesis-port-label${side === "right" ? " is-output" : ""}" x="${textX}" y="${y}" text-anchor="${side === "left" ? "start" : "end"}">${escapeHtml(synthesisShortText(port.name, 18))}</text>
    `;
  }).join("");
  return `
    <g class="compile-synthesis-port-rails">
      ${renderPins(leftPorts, "left")}
      ${renderPins(rightPorts, "right")}
    </g>
  `;
}

function renderSynthesisDiagramSvg(graph = {}, filter = "", options = {}) {
  const nodes = Array.isArray(graph.nodes) && graph.nodes.length
    ? graph.nodes
    : [{ id: "No HDL modules found", fileName: "" }];
  const topModule = graph.topModule || nodes[0]?.id || "";
  const expandedNodes = options.expandedNodes && typeof options.expandedNodes === "object" ? options.expandedNodes : {};
  const normalizedFilter = String(filter || "").trim().toLowerCase();
  const matchedNodeIds = new Set();
  const connectedMatchIds = new Set();
  if (normalizedFilter) {
    nodes.forEach((node) => {
      if (synthesisNodeHaystack(node).includes(normalizedFilter)) matchedNodeIds.add(node.id);
    });
    (Array.isArray(graph.edges) ? graph.edges : []).forEach((edge) => {
      if (synthesisEdgeHaystack(edge).includes(normalizedFilter) || matchedNodeIds.has(edge.from) || matchedNodeIds.has(edge.to)) {
        connectedMatchIds.add(edge.from);
        connectedMatchIds.add(edge.to);
      }
    });
  }
  const isNetlist = graph.netlist === true;
  const ordered = isNetlist
    ? nodes
    : [
        ...nodes.filter((node) => node.id === topModule),
        ...nodes.filter((node) => node.id !== topModule)
      ];
  const inputPorts = ordered.filter((node) => node.kind === "port" && node.direction === "input");
  const outputPorts = ordered.filter((node) => node.kind === "port" && node.direction === "output");
  const inoutPorts = ordered.filter((node) => node.kind === "port" && node.direction === "inout");
  const cells = ordered.filter((node) => node.kind !== "port" && node.kind !== "top");
  const topNodes = ordered.filter((node) => node.kind === "top" || node.id === `module:${topModule}` || node.id === topModule).slice(0, 1);
  const nodeById = new Map(ordered.map((node) => [node.id, node]));
  const expansionLevel = (node) => Math.max(0, Math.min(3, Math.round(Number(expandedNodes[node.id]) || 0)));
  const detailCount = (node) => synthesisDetailCount(node, graph, expansionLevel(node), nodeById);
  const nodeSize = (node) => synthesisNodeDimensions(node, expansionLevel(node), detailCount(node));
  const positions = new Map();
  let width = 1120;
  let height = 620;
  const placeVertical = (items, x, yStart, availableHeight = height - yStart - 40) => {
    const step = Math.max(66, Math.min(124, Math.floor(availableHeight / Math.max(1, items.length))));
    items.forEach((node, index) => {
      positions.set(node.id, { x, y: yStart + index * step });
    });
  };
  if (isNetlist) {
    const cellColumns = Math.min(3, Math.max(1, Math.ceil(Math.sqrt(Math.max(1, cells.length)) * 0.85)));
    const cellRows = Math.ceil(Math.max(1, cells.length) / cellColumns);
    const rowHeights = Array.from({ length: cellRows }, () => 96);
    cells.forEach((node, index) => {
      const row = Math.floor(index / cellColumns);
      rowHeights[row] = Math.max(rowHeights[row], nodeSize(node).height + 26);
    });
    const rowY = [];
    rowHeights.reduce((y, rowHeight, index) => {
      rowY[index] = y;
      return y + rowHeight;
    }, 126);
    const maxSidePorts = Math.max(inputPorts.length + inoutPorts.length, outputPorts.length, 1);
    width = Math.max(1040, 500 + cellColumns * 250);
    height = Math.max(620, 190 + Math.max(rowHeights.reduce((sum, rowHeight) => sum + rowHeight, 0), maxSidePorts * 66));
    topNodes.forEach((node) => {
      const size = nodeSize(node);
      positions.set(node.id, { x: (width - size.width) / 2, y: 24 });
    });
    placeVertical([...inputPorts, ...inoutPorts], 30, 116);
    placeVertical(outputPorts, width - 190, 116);
    cells.forEach((node, index) => {
      const column = index % cellColumns;
      const row = Math.floor(index / cellColumns);
      const columnX = 238 + column * 250;
      positions.set(node.id, { x: columnX, y: rowY[row] });
    });
  } else {
    const ranks = new Map();
    const queue = [{ id: topModule, rank: 0 }];
    while (queue.length) {
      const current = queue.shift();
      if (!current.id || ranks.has(current.id)) continue;
      ranks.set(current.id, current.rank);
      (Array.isArray(graph.edges) ? graph.edges : [])
        .filter((edge) => edge.from === current.id)
        .forEach((edge) => queue.push({ id: edge.to, rank: current.rank + 1 }));
    }
    ordered.forEach((node) => {
      if (!ranks.has(node.id)) ranks.set(node.id, Math.max(1, ranks.size ? Math.max(...ranks.values()) + 1 : 0));
    });
    const rankGroups = [...ranks.entries()].reduce((groups, [id, rank]) => {
      if (!groups.has(rank)) groups.set(rank, []);
      const node = nodeById.get(id);
      if (node) groups.get(rank).push(node);
      return groups;
    }, new Map());
    const sortedRanks = [...rankGroups.keys()].sort((a, b) => a - b);
    const largestRank = sortedRanks.reduce((max, rank) => Math.max(max, rankGroups.get(rank).length), 1);
    width = Math.max(980, 110 + sortedRanks.length * 245);
    height = Math.max(620, 116 + largestRank * 118);
    sortedRanks.forEach((rank, rankIndex) => {
      const group = rankGroups.get(rank);
      const x = 42 + rankIndex * 245;
      const step = Math.max(106, Math.floor((height - 120) / Math.max(1, group.length)));
      group.forEach((node, index) => {
        positions.set(node.id, { x, y: 62 + index * step });
      });
    });
  }
  const connectionPoint = (node, position, targetPosition, side = "auto") => {
    const size = nodeSize(node);
    const targetX = targetPosition?.x ?? position.x;
    const useRight = side === "right" || (side === "auto" && targetX >= position.x);
    return {
      x: useRight ? position.x + size.width : position.x,
      y: position.y + size.height / 2
    };
  };
  const edges = (Array.isArray(graph.edges) ? graph.edges : []).slice(0, 620);
  const renderedEdges = edges.map((edge, index) => {
    const from = positions.get(edge.from);
    const to = positions.get(edge.to);
    const fromNode = nodeById.get(edge.from);
    const toNode = nodeById.get(edge.to);
    if (!from || !to || !fromNode || !toNode) return "";
    const edgeMatches = Boolean(normalizedFilter && (synthesisEdgeHaystack(edge).includes(normalizedFilter) || connectedMatchIds.has(edge.from) || connectedMatchIds.has(edge.to)));
    const edgeMuted = Boolean(normalizedFilter && !edgeMatches);
    const start = connectionPoint(fromNode, from, to, "auto");
    const end = connectionPoint(toNode, to, from, "auto");
    const path = synthesisOrthogonalPath(start, end, index);
    const labelX = start.x + Math.max(22, (end.x - start.x) / 2);
    const labelY = start.y + (end.y - start.y) / 2 - 5 + ((index % 5) - 2) * 4;
    const label = [edge.net || edge.instance || "", Number(edge.width) > 1 ? `[${edge.width}]` : ""].filter(Boolean).join(" ");
    return `
      <path class="compile-synthesis-edge${edgeMatches ? " is-match" : ""}${edgeMuted ? " is-muted" : ""}" d="${path}" marker-end="url(#synthesis-arrow)"></path>
      ${label && index < 180 ? `<text class="compile-synthesis-instance${edgeMatches ? " is-match" : ""}${edgeMuted ? " is-muted" : ""}" x="${labelX + 4}" y="${labelY}">${escapeHtml(label)}</text>` : ""}
    `;
  });
  return `
    <svg class="compile-synthesis-svg" style="width:${width}px; min-height:${height}px;" viewBox="0 0 ${width} ${height}" role="img" aria-label="HDL synthesis module diagram">
      <defs>
        <marker id="synthesis-arrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto" markerUnits="strokeWidth">
          <path d="M0,0 L0,6 L9,3 z"></path>
        </marker>
      </defs>
      ${renderedEdges.join("")}
      ${ordered.map((node) => {
        const position = positions.get(node.id) || { x: 0, y: 0 };
        const level = expansionLevel(node);
        const size = nodeSize(node);
        const isTop = node.id === topModule || node.id === `module:${topModule}` || node.kind === "top";
        const nodeMatches = Boolean(normalizedFilter && (matchedNodeIds.has(node.id) || connectedMatchIds.has(node.id)));
        const nodeMuted = Boolean(normalizedFilter && !nodeMatches);
        return `
          <g class="compile-synthesis-node compile-synthesis-${escapeHtml(node.kind || "node")}${node.direction ? ` compile-synthesis-${escapeHtml(node.direction)}` : ""}${isTop ? " is-top" : ""}${level ? " is-expanded" : ""}${nodeMatches ? " is-match" : ""}${nodeMuted ? " is-muted" : ""}" data-synthesis-node-id="${escapeHtml(node.id)}">
            <rect x="${position.x}" y="${position.y}" width="${size.width}" height="${size.height}" rx="7"></rect>
            <text x="${position.x + 12}" y="${position.y + 22}">${escapeHtml(node.label || node.id)}</text>
            <text class="compile-synthesis-file" x="${position.x + 12}" y="${position.y + 40}">${escapeHtml(node.type || node.fileName || node.kind || (isTop ? "top module" : "module"))}</text>
             ${node.portCount && !level ? `<text class="compile-synthesis-file" x="${position.x + 12}" y="${position.y + Math.min(size.height - 9, 58)}">${Number(node.portCount)} ports</text>` : ""}
             ${renderSynthesisPortRails(node, graph, level, position, size)}
             ${renderSynthesisNodeDetail(node, graph, level, nodeById, position, size)}
          </g>
        `;
      }).join("")}
    </svg>
  `;
}

function renderCompileSynthesisDiagramWindow(project, file = activeCompileFile(project)) {
  const workspace = ensureCompileCode(project);
  if (!workspace.synthesisDiagramWindowOpen || !isHdlLanguage(file?.language)) return "";
  const synthesis = activeSynthesisDiagram(project, file);
  const graph = synthesis.graph || {};
  const zoom = Math.max(0.25, Math.min(3, Number(workspace.synthesisDiagramZoom || 1) || 1));
  const filter = String(workspace.synthesisDiagramFilter || "");
  const bounds = normalizeSynthesisWindowBounds(workspace.synthesisWindowBounds || {});
  workspace.synthesisWindowBounds = bounds;
  const sourceFiles = (workspace.files || []).filter((item) => isHdlLanguage(item.language) && item.role !== "testbench");
  const sourceGraph = hdlSynthesisGraphFromFiles(sourceFiles.length ? sourceFiles : (workspace.files || []).filter((item) => isHdlLanguage(item.language)));
  const moduleOptions = (Array.isArray(sourceGraph.nodes) ? sourceGraph.nodes : [])
    .filter((node) => node?.id)
    .slice(0, 80);
  return `
    <section class="compile-synthesis-diagram-window" aria-label="Synthesis diagram" style="left:${bounds.x}px; top:${bounds.y}px; width:${bounds.width}px; height:${bounds.height}px;">
      ${compileSynthesisResizeHandles()}
      <div class="compile-synthesis-diagram-heading" data-compile-synthesis-drag title="Drag to move synthesis window">
        <div>
          <strong>Schematic</strong>
          <span>${escapeHtml(graph.topModule ? `Top: ${graph.topModule}` : file?.fileName || "HDL source")}</span>
        </div>
        <div class="compile-synthesis-zoom-controls" aria-label="Synthesis diagram zoom controls">
          <button type="button" data-compile-synthesis-zoom="out" title="Zoom out">-</button>
          <button type="button" data-compile-synthesis-zoom="fit" title="Fit schematic to window">Fit</button>
          <span>${Math.round(zoom * 100)}%</span>
          <button type="button" data-compile-synthesis-zoom="in" title="Zoom in">+</button>
          <button type="button" data-compile-synthesis-zoom="reset" title="Reset zoom">100%</button>
        </div>
        <button class="compile-mini-window-close" type="button" data-compile-toggle-synthesis-diagram aria-label="Close synthesis diagram">&times;</button>
      </div>
      <div class="compile-synthesis-diagram-body">
        ${renderSynthesisExplorer(project, synthesis, graph)}
        <main class="compile-synthesis-main">
          <div class="compile-synthesis-toolbar">
            <input type="search" data-compile-synthesis-filter value="${escapeHtml(filter)}" placeholder="Find module, cell, net, source, instance..." aria-label="Find module, cell, net, source, or instance">
            <select class="compile-synthesis-top-select" data-compile-synthesis-top aria-label="Top module">
                <option value="">Auto detect</option>
                ${moduleOptions.map((node) => `<option value="${escapeHtml(node.id)}"${workspace.synthesisTopModule === node.id ? " selected" : ""}>${escapeHtml(node.label || node.id)}</option>`).join("")}
            </select>
          </div>
          ${renderSynthesisSummaryChips(synthesis, graph)}
          ${synthesis.available === false ? `<p class="compile-synthesis-warning">Yosys is not available, so this is a source-level module graph. Install OSS CAD Suite from Tools to produce a synthesized netlist.</p>` : ""}
          <div class="compile-synthesis-canvas" style="--synthesis-zoom: ${zoom};">
            <div class="compile-synthesis-zoom-stage">
              ${renderSynthesisDiagramSvg(graph, filter, { expandedNodes: workspace.synthesisExpandedNodes })}
            </div>
          </div>
        </main>
      </div>
    </section>
  `;
}

function showCompileSynthesisDiagram(project, file = activeCompileFile(project)) {
  if (!project || !isHdlLanguage(file?.language)) {
    setStatus("Synthesis diagrams are available for Verilog and SystemVerilog files.");
    return;
  }
  const workspace = ensureCompileCode(project);
  const designFiles = (workspace.files || []).filter((item) => isHdlLanguage(item.language) && item.role !== "testbench");
  const fallbackFiles = designFiles.length ? designFiles : (workspace.files || []);
  workspace.synthesisDiagramWindowOpen = true;
  workspace.synthesisDiagramZoom = Math.max(0.25, Math.min(3, Number(workspace.synthesisDiagramZoom || 1) || 1));
  workspace.synthesis = workspace.synthesis || {
    graph: hdlSynthesisGraphFromFiles(fallbackFiles),
    tool: "Source parser",
    available: false,
    generatedAt: new Date().toISOString()
  };
  setStatus("Synthesis diagram opened.");
  scheduleAutosave(900);
  renderSectionContent(project);
}

function renderCompileActiveOutputPanel(project, file = activeCompileFile(project)) {
  const workspace = ensureCompileCode(project);
  const activePanel = activeCompilePanel(project, file);
  if (activePanel === "messages") return renderCompileMessagesPanel(workspace);
  if (activePanel === "terminal") return renderCompileSystemTerminal(workspace, project);
  if (activePanel === "scope") return renderCompileScopePanel(project, file);
  if (activePanel === "syntax") return renderCompileSyntaxPanel(workspace, file);
  return renderCompileConsolePanel(project, file);
}

function renderCompileMenuItems(items = []) {
  return items.map((item) => {
    if (item.separator) return `<span class="compile-ide-menu-separator" role="separator"></span>`;
    if (item.heading) return `<strong class="compile-ide-menu-heading">${escapeHtml(item.heading)}</strong>`;
    return `
      <button type="button" data-compile-menu-action="${escapeHtml(item.action)}"${item.disabled ? " disabled" : ""}>
        <span>${escapeHtml(item.label)}</span>
        ${item.shortcut ? `<small>${escapeHtml(item.shortcut)}</small>` : ""}
      </button>
    `;
  }).join("");
}

function printableSectionRich(section = {}) {
  return richHasContent(section.richDescription) ? section.richDescription : section.rich;
}

function printablePortfolioProjectSection(section = {}, depth = 0) {
  const children = (section.items || section.children || []).filter((item) =>
    item?.title || item?.description || richHasContent(printableSectionRich(item)) || item?.url || (item?.items || item?.children || []).length
  );
  const headingTag = depth > 0 ? "h4" : "h3";
  const sectionRich = printableSectionRich(section);
  const rich = richHasContent(sectionRich) ? renderRichContent(sectionRich, section.description || "") : "";
  const description = !rich && section.description ? `<p>${renderMultilineInlineText(section.description)}</p>` : "";
  const link = section.url ? `<p><a href="${escapeHtml(normalizeLinkTarget(section.url, { assumeWeb: true }))}">${escapeHtml(section.title || section.url)}</a></p>` : "";
  return `
    <section class="print-project-section depth-${depth}">
      <${headingTag}>${escapeHtml(section.title || section.label || "Section")}</${headingTag}>
      ${rich || description}
      ${link}
      ${children.length ? `<div class="print-section-children">${children.map((item) => printablePortfolioProjectSection(item, depth + 1)).join("")}</div>` : ""}
    </section>
  `;
}

function printablePortfolioProjectHasContent(project = {}) {
  return Boolean(
    project?.title ||
    project?.summary ||
    richHasContent(project?.summaryRich) ||
    (project?.portfolioView?.sections || []).some(previewSectionHasRenderableContent)
  );
}

function buildPrintablePortfolioHtml() {
  const profile = normalizeProfile(catalog.profile || savedPortfolioCatalog.profile || {});
  const globals = parsedPortfolioGlobals();
  const siteContent = globals.siteContent || normalizeSiteContent(catalog.siteContent || {});
  const projects = (catalog.projects || [])
    .map((project) => parseProjectForPortfolio(project))
    .filter(printablePortfolioProjectHasContent);
  const categories = catalog.categories || [];
  const baseHref = `${window.location.origin}/`;
  const contact = [
    profile.email ? `<a href="mailto:${escapeHtml(profile.email)}">${escapeHtml(profile.email)}</a>` : "",
    profile.phone ? `<a href="tel:${escapeHtml(profile.phone)}">${escapeHtml(profile.phone)}</a>` : "",
    profile.githubUrl ? `<a href="${escapeHtml(normalizeLinkTarget(profile.githubUrl, { assumeWeb: true }))}">GitHub</a>` : "",
    profile.linkedinUrl ? `<a href="${escapeHtml(normalizeLinkTarget(profile.linkedinUrl, { assumeWeb: true }))}">LinkedIn</a>` : "",
    profile.websiteUrl ? `<a href="${escapeHtml(normalizeLinkTarget(profile.websiteUrl, { assumeWeb: true }))}">Website</a>` : ""
  ].filter(Boolean).join(" · ");
  const categoryName = (id = "") => categories.find((category) => category.id === id)?.label || displayTitle(id || "Project", "Project");
  const projectCards = projects.map((project) => {
    const view = project.portfolioView || {};
    const sections = (view.sections || []).filter(previewSectionHasRenderableContent);
    return `
      <article class="print-project">
        <header>
          <p>${escapeHtml(categoryName(project.category))}${view.status && view.showStatus !== false ? ` · ${escapeHtml(view.status)}` : ""}</p>
          <h2>${escapeHtml(view.title || project.title || "Project")}</h2>
        </header>
        ${sections.map((section) => printablePortfolioProjectSection(section)).join("")}
      </article>
    `;
  }).join("");
  const personalSections = (catalog.siteSections || [])
    .filter(siteSectionRenderable)
    .map((section) => `
      <section class="print-project-section">
        <h3>${escapeHtml(section.title || "Portfolio Section")}</h3>
        ${richHasContent(printableSectionRich(section)) ? renderRichContent(printableSectionRich(section), section.description || "") : section.description ? `<p>${renderMultilineInlineText(section.description)}</p>` : ""}
      </section>
    `).join("");

  return `<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <base href="${baseHref}" />
    <title>${escapeHtml(profile.displayName || "Portfolio")} print portfolio</title>
    <style>
      @page { margin: 0.55in; }
      * { box-sizing: border-box; }
      body { margin: 0; color: #17202a; background: #ffffff; font: 11pt/1.45 Arial, sans-serif; }
      a { color: #0f5fb8; text-decoration: none; }
      .print-shell { max-width: 8.4in; margin: 0 auto; }
      .print-hero { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 20px; align-items: start; padding-bottom: 18px; border-bottom: 2px solid #1f6ed4; }
      .print-hero h1 { margin: 0 0 6px; font-size: 27pt; line-height: 1.08; }
      .print-hero p { margin: 4px 0; color: #334155; }
      .print-avatar { width: 84px; height: 84px; object-fit: cover; border-radius: 8px; border: 1px solid #c9deea; }
      .print-summary { margin: 14px 0 18px; padding: 11px 14px; border-left: 4px solid #1f6ed4; background: #f4fbff; }
      .print-project { page-break-inside: avoid; margin: 0 0 18px; padding: 0 0 14px; border-bottom: 1px solid #d8e8f2; }
      .print-project header p { margin: 0 0 3px; color: #0f7592; font-weight: 700; text-transform: uppercase; font-size: 8.5pt; letter-spacing: .02em; }
      .print-project h2 { margin: 0 0 9px; font-size: 16pt; line-height: 1.15; }
      .print-project-section { margin: 9px 0; }
      .print-project-section h3 { margin: 0 0 5px; font-size: 12.5pt; color: #17202a; }
      .print-project-section h4 { margin: 8px 0 4px; font-size: 10.5pt; color: #334155; }
      .print-project-section p { margin: 0 0 7px; }
      .rich-content p, .rich-paragraph { margin: 0 0 7px; }
      .rich-image, .rich-video { margin: 8px 0; max-width: 100%; }
      .rich-image img, .rich-video img, .rich-video video { max-width: 100%; height: auto; }
      .rich-table { width: 100%; border-collapse: collapse; margin: 7px 0; }
      .rich-table td, .rich-table th { border: 1px solid #b8d8e8; padding: 5px 7px; vertical-align: top; }
      .rich-code { white-space: pre-wrap; padding: 8px; border: 1px solid #d8e8f2; background: #f8fbff; font: 8.5pt/1.35 Consolas, monospace; }
      @media print { .print-project { break-inside: avoid; } }
    </style>
  </head>
  <body>
    <main class="print-shell">
      <section class="print-hero">
        <div>
          <h1>${escapeHtml(profile.displayName || "Portfolio")}</h1>
          <p><strong>${escapeHtml(siteContent.heroTitle || profile.portfolioLabel || "Engineering Portfolio")}</strong></p>
          ${siteContent.heroCopy ? `<p>${renderMultilineInlineText(siteContent.heroCopy)}</p>` : ""}
          ${contact ? `<p>${contact}</p>` : ""}
        </div>
        ${profile.profileImage ? `<img class="print-avatar" src="${escapeHtml(normalizeLinkTarget(profile.profileImage))}" alt="${escapeHtml(profile.displayName || "Profile photo")}">` : ""}
      </section>
      ${profile.contactIntro ? `<section class="print-summary">${renderMultilineInlineText(profile.contactIntro)}</section>` : ""}
      ${personalSections}
      ${projectCards || `<p>No saved project content is available to print yet.</p>`}
    </main>
    <script>
      window.addEventListener("load", () => setTimeout(() => window.print(), 250));
    </script>
  </body>
</html>`;
}

async function printPortfolioDocument() {
  if (!(await commitActiveProjectEdits())) return;
  const printWindow = window.open("", "_blank", "width=980,height=1100");
  if (!printWindow) {
    setStatus("The print window was blocked. Allow pop-ups for the builder, then choose File > Print portfolio again.");
    return;
  }
  printWindow.document.open();
  printWindow.document.write(buildPrintablePortfolioHtml());
  printWindow.document.close();
  setStatus("Print portfolio view opened. Choose Save as PDF in the print dialog if you want a PDF copy.");
}

