analogMixedCanvas?.addEventListener("drop", (event) => {
  const project = activeAnalogMixedProject();
  if (!project) return;
  const workspace = normalizeAnalogMixedWorkspace(project);
  const libraryId = event.dataTransfer?.getData("application/x-omb-am-library") || analogMixedDraggingLibraryId;
  if (!libraryId) return;
  event.preventDefault();
  const point = analogMixedPointFromEvent(event, workspace);
  analogMixedPlaceLibraryItem(project, libraryId, point, { stage: workspace.activeStage });
  analogMixedDraggingLibraryId = "";
});
analogMixedCanvas?.addEventListener("contextmenu", (event) => {
  if (!analogMixedDialog?.open) return;
  const project = activeAnalogMixedProject();
  if (!project) return;
  const workspace = normalizeAnalogMixedWorkspace(project);
  if (analogMixedWireStart && workspace.activeTool === "wire") {
    event.preventDefault();
    const finishPoint = workspace.activeStage === "ic-layout"
      ? { ...analogMixedPointFromEvent(event, workspace), ref: { type: "layout-point" } }
      : analogMixedCapturePointFromEvent(event, workspace);
    analogMixedFinishActiveWire(project, finishPoint);
    return;
  }
  if (!["select", "pan"].includes(workspace.activeTool)) {
    event.preventDefault();
    analogMixedAbortActiveCommand("Active placement or wiring command canceled.");
    return;
  }
  const wireTarget = event.target.closest?.("[data-am-wire]");
  const componentTarget = event.target.closest?.("[data-am-component]");
  const layoutRouteTarget = event.target.closest?.("[data-am-layout-route]");
  const layoutTarget = event.target.closest?.("[data-am-layout-object]");
  event.preventDefault();
  if (wireTarget) {
    workspace.selectedWireId = wireTarget.dataset.amWire || "";
    workspace.selectedComponentId = "";
    renderAnalogMixedWorkspace();
    analogMixedShowContextMenu(event, { type: "wire", id: workspace.selectedWireId });
    return;
  }
  if (componentTarget) {
    workspace.selectedComponentId = componentTarget.dataset.amComponent || "";
    workspace.selectedWireId = "";
    renderAnalogMixedWorkspace();
    analogMixedShowContextMenu(event, { type: "component", id: workspace.selectedComponentId });
    return;
  }
  if (layoutRouteTarget) {
    analogMixedShowContextMenu(event, { type: "layout-route", id: layoutRouteTarget.dataset.amLayoutRoute || "" });
    return;
  }
  if (layoutTarget) {
    const layoutData = analogMixedNormalizeIcLayout(workspace);
    const layoutObject = layoutData.layoutObjects.find((item) => item.id === layoutTarget.dataset.amLayoutObject);
    if (layoutObject?.sourceComponentId) {
      workspace.selectedComponentId = layoutObject.sourceComponentId;
      workspace.selectedWireId = "";
    }
    renderAnalogMixedWorkspace();
    analogMixedShowContextMenu(event, { type: "layout-object", id: layoutObject?.id || "" });
    return;
  }
  analogMixedShowContextMenu(event, { type: "canvas" });
});
analogMixedDialog?.addEventListener("click", (event) => {
  const project = activeAnalogMixedProject();
  if (!project) return;
  const workspace = normalizeAnalogMixedWorkspace(project);
  if (event.target.closest("[data-am-tool-window-close]")) {
    workspace.activeToolWindow = "";
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    return;
  }
  const windowAction = event.target.closest("[data-am-window-action]");
  if (windowAction) {
    const action = windowAction.dataset.amWindowAction || "";
    if (action === "run-drc") return analogMixedRunChecks("drc");
    if (action === "run-erc") return analogMixedRunChecks("erc");
    if (action === "refresh-netlist") return analogMixedGenerateNetlistFromBackend();
    if (action === "copy-netlist") {
      navigator.clipboard?.writeText(workspace.netlist || "");
      analogMixedSetStatus("Netlist copied to clipboard.");
      return;
    }
    if (action === "run-spice") return analogMixedRunSpiceSimulation(workspace.toolWindows.spice.analysis || "op");
    if (action === "plan-spice") return analogMixedPrepareSpiceSimulationPlan(workspace.toolWindows.spice.analysis || "tran");
  }
  const operationRun = event.target.closest("[data-am-operation-run]");
  if (operationRun) {
    analogMixedExecuteOperation(operationRun.dataset.amOperationRun || "");
    return;
  }
  const hubSuite = event.target.closest("[data-am-hub-suite]");
  if (hubSuite) {
    const suite = analogMixedSetSuite(workspace, hubSuite.dataset.amHubSuite || "ic");
    workspace.activeHubSuite = suite.id;
    workspace.toolHubOpen = true;
    workspace.activeDesignTool = "";
    workspace.activeToolWindow = "";
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    analogMixedSetStatus(`${suite.label} tools expanded.`);
    return;
  }
  const designTool = event.target.closest("[data-am-design-tool]");
  if (designTool) {
    analogMixedOpenDesignTool(designTool.dataset.amDesignTool || "");
    return;
  }
  const paneToggle = event.target.closest("[data-am-pane-toggle]");
  if (paneToggle) {
    const pane = paneToggle.dataset.amPaneToggle || "";
    if (pane === "library") workspace.libraryCollapsed = !workspace.libraryCollapsed;
    if (pane === "inspector") workspace.inspectorCollapsed = !workspace.inspectorCollapsed;
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    return;
  }
  const icLayoutToolButton = event.target.closest("[data-am-ic-layout-tool]");
  if (icLayoutToolButton) {
    analogMixedSetIcLayoutTool(icLayoutToolButton.dataset.amIcLayoutTool || "select");
    return;
  }
  const layerToggleButton = event.target.closest("[data-am-layer-toggle]");
  if (layerToggleButton) {
    analogMixedToggleIcLayerVisibility(layerToggleButton.dataset.amLayerToggle || "");
    return;
  }
  const toolButton = event.target.closest("[data-am-tool]");
  if (toolButton) {
    analogMixedSetTool(toolButton.dataset.amTool || "select");
    return;
  }
  const libraryPlaceButton = event.target.closest("[data-am-library-place]");
  if (libraryPlaceButton) {
    analogMixedArmLibraryPlacement(libraryPlaceButton.dataset.amLibraryPlace || workspace.selectedLibraryId);
    return;
  }
  const libraryButton = event.target.closest("[data-am-library]");
  if (libraryButton) {
    workspace.selectedLibraryId = libraryButton.dataset.amLibrary || "resistor";
    const selectedItem = analogMixedLibraryItem(workspace.selectedLibraryId);
    if (workspace.activeTool === "place") workspace.activeTool = "select";
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    analogMixedSetStatus(`${selectedItem.label} selected. Click + to place it, or drag it from the library into the workspace.`);
    return;
  }
  const stageButton = event.target.closest("[data-am-stage]");
  if (stageButton) {
    analogMixedOpenStageWithinSuite(workspace, stageButton.dataset.amStage || "schematic");
    workspace.toolHubOpen = false;
    workspace.activeDesignTool = "";
    analogMixedClearActiveWireRoute();
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    analogMixedSetStatus(`${analogMixedStages.find((stage) => stage.id === workspace.activeStage)?.label || "Stage"} stage opened.`);
    return;
  }
  const viewAction = event.target.closest("[data-am-view-action]");
  if (viewAction) {
    const action = viewAction.dataset.amViewAction || "";
    if (action === "zoom-in") analogMixedZoom(0.15);
    if (action === "zoom-out") analogMixedZoom(-0.15);
    if (action === "fit") analogMixedFitCanvas();
    if (action === "drc") analogMixedRunChecks("drc");
    if (action === "erc") analogMixedRunChecks("erc");
    if (action === "3d") {
      analogMixedSetSuite(workspace, "pcb", { preferredStage: "3d-view" });
      workspace.activeStage = "3d-view";
      workspace.show3dPreview = true;
      markDraftNeedsSave();
      scheduleAutosave();
      renderAnalogMixedWorkspace();
      analogMixedSetStatus("3D physical planning stage opened.");
    }
    return;
  }
  const stageCommand = event.target.closest("[data-am-stage-command]");
  if (stageCommand) {
    analogMixedHandleStageCommand(stageCommand.dataset.amStageCommand || "");
    return;
  }
  const panelButton = event.target.closest("[data-am-panel]");
  if (panelButton) {
    workspace.activePanel = panelButton.dataset.amPanel || "netlist";
    renderAnalogMixedWorkspace();
    return;
  }
  const componentAction = event.target.closest("[data-am-component-action]");
  if (componentAction) {
    const selected = workspace.components.find((component) => component.id === workspace.selectedComponentId);
    if (!selected) return;
    const action = componentAction.dataset.amComponentAction;
    if (action === "delete") analogMixedDeleteSelected();
    if (action === "rotate") {
      selected.rotation = (Number(selected.rotation) + 90) % 360;
      markDraftNeedsSave();
      scheduleAutosave();
      renderAnalogMixedWorkspace();
    }
    if (action === "mirror") {
      selected.mirrored = !selected.mirrored;
      markDraftNeedsSave();
      scheduleAutosave();
      renderAnalogMixedWorkspace();
    }
    if (action === "duplicate") {
      analogMixedAddComponent(project, selected.type, { x: selected.x + 60, y: selected.y + 60 });
    }
    if (action === "add-param") {
      const rawKey = String(window.prompt("Parameter name, for example W, L, nf, m, ad, as, pd, ps", "") || "").trim();
      if (!rawKey) return;
      const key = rawKey.replace(/[^A-Za-z0-9_]/g, "_");
      selected.parameters = selected.parameters && typeof selected.parameters === "object" ? selected.parameters : {};
      if (!Object.prototype.hasOwnProperty.call(selected.parameters, key)) selected.parameters[key] = "";
      markDraftNeedsSave();
      scheduleAutosave();
      renderAnalogMixedWorkspace();
      analogMixedSetStatus(`Added parameter ${key} to ${selected.label || "selected device"}.`);
    }
    return;
  }
  const wireAction = event.target.closest("[data-am-wire-action]");
  if (wireAction) {
    const action = wireAction.dataset.amWireAction || "";
    if (action === "rename") analogMixedRenameSelectedWire();
    if (action === "delete") analogMixedDeleteSelectedWire();
    return;
  }
  const componentParamDelete = event.target.closest("[data-am-component-param-delete]");
  if (componentParamDelete) {
    const selected = workspace.components.find((component) => component.id === workspace.selectedComponentId);
    if (!selected) return;
    const key = componentParamDelete.dataset.amComponentParamDelete || "";
    selected.parameters = selected.parameters && typeof selected.parameters === "object" ? selected.parameters : {};
    delete selected.parameters[key];
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    analogMixedSetStatus(`Deleted parameter ${key}.`);
    return;
  }
  const menuAction = event.target.closest("[data-am-menu-action]");
  if (menuAction) {
    analogMixedHandleMenuAction(menuAction.dataset.amMenuAction || "");
    return;
  }
  const menuItem = event.target.closest("[data-am-menu-item]");
  if (menuItem) {
    handleAnalogMixedMenuItem(menuItem.dataset.amMenuItem || "");
  }
});
analogMixedContextMenu?.addEventListener("click", async (event) => {
  const button = event.target.closest("[data-am-context-action]");
  if (!button) return;
  event.preventDefault();
  const action = button.dataset.amContextAction || "";
  analogMixedHideContextMenu();
  await analogMixedHandleContextAction(action);
});
document.addEventListener("pointerdown", (event) => {
  if (!analogMixedContextMenu || analogMixedContextMenu.hidden) return;
  if (event.target.closest?.("#analog-mixed-context-menu")) return;
  analogMixedHideContextMenu();
}, true);
analogMixedDialog?.addEventListener("input", (event) => {
  const project = activeAnalogMixedProject();
  if (!project) return;
  const workspace = normalizeAnalogMixedWorkspace(project);
  if (event.target.dataset.amWireField) {
    const wire = workspace.wires.find((item) => item.id === workspace.selectedWireId);
    if (!wire) return;
    wire[event.target.dataset.amWireField] = event.target.value.replace(/\s+/g, "_");
    markDraftNeedsSave();
    scheduleAutosave();
    analogMixedSetStatus("Updated selected wire.");
    return;
  }
  if (event.target.dataset.amComponentField) {
    const selected = workspace.components.find((component) => component.id === workspace.selectedComponentId);
    if (!selected) return;
    selected[event.target.dataset.amComponentField] = event.target.value;
    if (workspace.stageData?.["ic-layout"]) {
      const layoutData = analogMixedNormalizeIcLayout(workspace);
      layoutData.layoutObjects = layoutData.layoutObjects.map((object, index) => {
        if (object.sourceComponentId !== selected.id) return object;
        const refreshed = analogMixedLayoutObjectFromComponent(selected, index, workspace);
        return { ...object, ...refreshed, id: object.id, x: object.x, y: object.y, width: object.width, height: object.height };
      });
      workspace.stageData["ic-layout"] = layoutData;
    }
    markDraftNeedsSave();
    scheduleAutosave();
    analogMixedSetStatus(`Updated ${selected.label || "selected component"}.`);
    return;
  }
  if (event.target.dataset.amComponentParam) {
    const selected = workspace.components.find((component) => component.id === workspace.selectedComponentId);
    if (!selected) return;
    selected.parameters = selected.parameters && typeof selected.parameters === "object" ? selected.parameters : {};
    selected.parameters[event.target.dataset.amComponentParam] = event.target.value;
    if (workspace.stageData?.["ic-layout"]) {
      const layoutData = analogMixedNormalizeIcLayout(workspace);
      layoutData.layoutObjects = layoutData.layoutObjects.map((object, index) => {
        if (object.sourceComponentId !== selected.id) return object;
        const refreshed = analogMixedLayoutObjectFromComponent(selected, index, workspace);
        return { ...object, ...refreshed, id: object.id, x: object.x, y: object.y, width: object.width, height: object.height };
      });
      workspace.stageData["ic-layout"] = layoutData;
    }
    markDraftNeedsSave();
    scheduleAutosave();
    analogMixedSetStatus(`Updated ${selected.label || "selected device"} parameter.`);
    return;
  }
  if (event.target.dataset.amParameter) {
    workspace.parameters[workspace.focus][event.target.dataset.amParameter] = event.target.value;
    markDraftNeedsSave();
    scheduleAutosave();
    return;
  }
  if (event.target.dataset.amNotes !== undefined) {
    workspace.notes = event.target.value.split(/\r?\n/);
    markDraftNeedsSave();
    scheduleAutosave();
  }
  if (event.target.dataset.amOperationFilter !== undefined) {
    workspace.toolWindows.operations.filter = event.target.value || "";
    workspace.operationPaletteFilter = workspace.toolWindows.operations.filter;
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    return;
  }
});
analogMixedDialog?.addEventListener("change", async (event) => {
  const project = activeAnalogMixedProject();
  const workspace = project ? normalizeAnalogMixedWorkspace(project) : null;
  if (workspace && event.target.dataset.amDrcFilter) {
    workspace.toolWindows.drc[event.target.dataset.amDrcFilter] = event.target.checked;
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    return;
  }
  if (workspace && event.target.dataset.amDrcKind !== undefined) {
    workspace.toolWindows.drc.kind = event.target.value || "drc";
    analogMixedRunChecks(workspace.toolWindows.drc.kind);
    return;
  }
  if (workspace && event.target.dataset.amDrcScope !== undefined) {
    workspace.toolWindows.drc.scope = event.target.value || "all";
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    return;
  }
  if (workspace && event.target.dataset.amNetlistSetting) {
    const key = event.target.dataset.amNetlistSetting;
    workspace.toolWindows.netlist[key] = event.target.type === "checkbox" ? event.target.checked : event.target.value;
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    return;
  }
  if (workspace && event.target.dataset.amSpiceSetting) {
    const key = event.target.dataset.amSpiceSetting;
    workspace.toolWindows.spice[key] = event.target.type === "checkbox" ? event.target.checked : event.target.value;
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    return;
  }
  if (workspace && event.target.dataset.amOperationMenu !== undefined) {
    workspace.toolWindows.operations.menu = event.target.value || "all";
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    return;
  }
  if (workspace && event.target.dataset.amOperationLimit !== undefined) {
    workspace.toolWindows.operations.limit = Math.max(30, Math.min(300, Number(event.target.value) || 120));
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    return;
  }
  if (workspace && event.target.dataset.amPhysical3dSetting) {
    const key = event.target.dataset.amPhysical3dSetting;
    workspace.toolWindows.physical3d[key] = event.target.type === "checkbox" ? event.target.checked : event.target.value;
    markDraftNeedsSave();
    scheduleAutosave();
    renderAnalogMixedWorkspace();
    return;
  }
  if (event.target.dataset.amIcWorkflowLane !== undefined) {
    await analogMixedSetIcWorkflowLane(event.target.value || "layout-suite");
    return;
  }
  if (!event.target.dataset.amComponentField) return;
  renderAnalogMixedWorkspace();
});
document.addEventListener("keydown", handleAnalogMixedKeyboard, true);

saveDraftButton.addEventListener("click", () => saveCatalog("/api/save-draft", "Draft saved"));
applyCatalogButton.addEventListener("click", () => {
  saveCatalog("/api/apply-catalog", "Catalog applied and pushed");
});

window.addEventListener("builder-menu-action", (event) => {
  const type = event.detail?.type || "";
  if (type === "new-project") addProjectButton?.click();
  if (type === "publishing-target") publishTargetOpen?.click();
  if (type === "save-draft") saveDraftButton?.click();
  if (type === "apply-site") applyCatalogButton?.click();
  if (type === "portfolio-preview") openPortfolioPreviewButton?.click();
  if (type === "print-portfolio") printPortfolioDocument();
  if (type === "builder-guide") builderGuideOpen?.click();
  if (type === "check-updates") checkForAppUpdates({ force: true, manual: true });
  if (type === "preferences") openPreferencesDialog();
  if (type === "set-theme") setBuilderTheme(event.detail?.theme || "light");
});

document.addEventListener("keydown", (event) => {
  void handleGlobalKeyboardShortcuts(event);
}, true);
document.addEventListener("wheel", handleBuilderZoomWheel, { passive: false });

loadBuilderPreferences();
renderSelectionInspectorOptions();
enableDraggableDialogs();

window.addEventListener("beforeunload", () => {
  clearTimeout(autosaveTimer);
  const payload = JSON.stringify({ catalog });
  if (navigator.sendBeacon) {
    navigator.sendBeacon("/api/save-draft", new Blob([payload], { type: "application/json" }));
  }
});
// Legacy global hook kept inert; scoped editor listeners above own the context menu.
document.addEventListener("builder-disabled-contextmenu", (event) => {
    const editor = event.target.closest("[data-rich-editor]");
    const block = event.target.closest(".rich-block");
    if (!editor && !block) return;

    event.preventDefault();

    // Determine which editor and block are active.
    activeSummaryEditor = editor || block.closest("[data-rich-editor]");
    selectRichBlock(block || currentRichBlock(activeSummaryEditor));

    // Synchronize the context‑menu controls (font, size, color).
    syncRichContextMenuControls(activeSummaryBlock);

    // Position and show the context menu.
    summaryContextMenu.style.left = `${event.clientX}px`;
    summaryContextMenu.style.top = `${event.clientY}px`;
    summaryContextMenu.hidden = false;
}, true);
document.addEventListener("builder-disabled-click", () => {
    summaryContextMenu.hidden = true;
});

loadData().catch((error) => {
  setStatus(error.message || "Builder failed to load.");
});
scheduleAppUpdateChecks();
